import React from 'react';
import { Swiper, SwiperSlide } from 'swiper/react';
import 'swiper/swiper-bundle.css';
import 'swiper/css/effect-coverflow';
import { EffectCoverflow } from 'swiper/modules';

const CustomSlider = ({ slides }) => {
  return (
    <Swiper
    effect={'coverflow'}
    grabCursor={true}
    centeredSlides={true}
    slidesPerView={'auto'}
    coverflowEffect={{
      rotate: 50,
      stretch: 0,
      depth: 100,
      modifier: 1,
      slideShadows: true,
    }}
    pagination={true}
    loop
    autoplay
    modules={[EffectCoverflow]}
    className="mySwiper"
    >
      {slides.map((slide, index) => (
        <SwiperSlide key={index} style={{maxWidth:'80%'}}>
          <img
            src={slide.src}
            alt={`Slide ${index + 1}`}
            style={{
              width: '100%',
              height: '100%',
              objectFit: 'cover',
              borderRadius: '10px',
            }}
          />
          {slide.caption && (
              <div
                style={{
                  position: 'absolute',
                  bottom: '16px',
                  backgroundColor: 'rgba(0, 0, 0, 0.5)',
                  color: 'white',
                  padding: '8px 16px',
                  borderRadius: '8px',
                  fontSize: '14px',
                  textAlign: 'center',
                  maxWidth: '80%',
                  left: '16px'
                }}
              >
                {slide.caption}
              </div>
          )}
        </SwiperSlide>
      ))}
    </Swiper>
  );
};

export default CustomSlider;
